window.ScripturaLexicons.BDAG_PART_0038 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-axiopistos-bdag\" data-source=\"BDAG\" data-search=\"ἀξιόπιστος axiopistos confiável digno crédito aparência pretensioso Diógneto Inácio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀξιόπιστος</td><td>Adjetivo</td><td>confiável; aparentemente confiável; pretensioso</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-axioplokos-bdag\" data-source=\"BDAG\" data-search=\"ἀξιόπλοκος axioplokos dignamente entretecido coroa Inácio Magnésia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀξιόπλοκος</td><td>Adjetivo</td><td>dignamente entretecido</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-axioprepes-bdag\" data-source=\"BDAG\" data-search=\"ἀξιοπρεπής axioprepes digno honra estimadíssimo bispo Inácio Romanos Magnésia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀξιοπρεπής</td><td>Adjetivo</td><td>digno de honra; estimadíssimo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-axios-bdag\" data-source=\"BDAG\" data-search=\"ἄξιος axios correspondente comparável digno merecedor Mateus Lucas Atos Romanos Coríntios Timóteo Hebreus Apocalipse BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄξιος</td><td>Adjetivo</td><td>correspondente; digno; merecedor</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-axioo-bdag\" data-source=\"BDAG\" data-search=\"ἀξιόω axioo considerar digno julgar opinar pedir Atos Lucas Timóteo Hebreus Tessalonicenses BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀξιόω</td><td>Verbo</td><td>considerar digno; julgar; pedir</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-axios-adv-bdag\" data-source=\"BDAG\" data-search=\"ἀξίως axios dignamente apropriadamente Tessalonicenses Colossenses Romanos Filipenses Efésios BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀξίως</td><td>Advérbio</td><td>dignamente; de modo apropriado</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aoiketos-bdag\" data-source=\"BDAG\" data-search=\"ἀοίκητος aoiketos desabitado inabitável Papias BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀοίκητος</td><td>Adjetivo</td><td>desabitado; inabitável</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aoikos-bdag\" data-source=\"BDAG\" data-search=\"ἄοικος aoikos sem casa deserto Papias BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄοικος</td><td>Adjetivo</td><td>sem casa; deserto</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aoknos-bdag\" data-source=\"BDAG\" data-search=\"ἄοκνος aoknos incansável resoluto sem hesitação Inácio Policarpo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄοκνος</td><td>Adjetivo</td><td>incansável; resoluto</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aoknos-adv-bdag\" data-source=\"BDAG\" data-search=\"ἀόκνως aoknos sem hesitação Clemente serviço público BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀόκνως</td><td>Advérbio</td><td>sem hesitação</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aoratos-bdag\" data-source=\"BDAG\" data-search=\"ἀόρατος aoratos invisível Deus Cristo mundo invisível Romanos Colossenses Timóteo Hebreus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀόρατος</td><td>Adjetivo</td><td>invisível; não visto</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aorgetos-bdag\" data-source=\"BDAG\" data-search=\"ἀόργητος aorgetos livre ira sem paixão Clemente Diógneto Inácio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀόργητος</td><td>Adjetivo</td><td>livre de ira; sem paixão</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apangello-bdag\" data-source=\"BDAG\" data-search=\"ἀπαγγέλλω apangello relatar anunciar contar proclamar Mateus Marcos Lucas João Atos Hebreus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαγγέλλω</td><td>Verbo</td><td>relatar; anunciar; proclamar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apancho-bdag\" data-source=\"BDAG\" data-search=\"ἀπάγχω apancho enforcar Judas Mateus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπάγχω</td><td>Verbo</td><td>enforcar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apago-bdag\" data-source=\"BDAG\" data-search=\"ἀπάγω apago levar conduzir afastar execução caminho desviar Mateus Marcos Lucas Atos João Coríntios Apocalipse BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπάγω</td><td>Verbo</td><td>levar; conduzir; afastar; desviar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apathes-bdag\" data-source=\"BDAG\" data-search=\"ἀπαθής apathes livre sofrimento ileso Cristo Papias BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαθής</td><td>Adjetivo</td><td>livre de sofrimento; ileso</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apaideutos-bdag\" data-source=\"BDAG\" data-search=\"ἀπαίδευτος apaideutos sem instrução inculto especulações Timóteo Clemente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαίδευτος</td><td>Adjetivo</td><td>sem instrução; inculto</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apairo-bdag\" data-source=\"BDAG\" data-search=\"ἀπαίρω apairo tirar partir deixar noivo Mateus Marcos Lucas Atos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαίρω</td><td>Verbo</td><td>tirar; partir; deixar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apaiteo-bdag\" data-source=\"BDAG\" data-search=\"ἀπαιτέω apaiteo exigir pedir de volta cobrar desejar Lucas Pedro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαιτέω</td><td>Verbo</td><td>exigir de volta; exigir; desejar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apalgeo-bdag\" data-source=\"BDAG\" data-search=\"ἀπαλγέω apalgeo insensível sentimento desanimado Efésios BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαλγέω</td><td>Verbo</td><td>tornar-se insensível; desanimar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apallasso-bdag\" data-source=\"BDAG\" data-search=\"ἀπαλλάσσω apallasso libertar soltar partir deixar acordo adversário Hebreus Lucas Atos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαλλάσσω</td><td>Verbo</td><td>libertar; partir; reconciliar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apallotrioo-bdag\" data-source=\"BDAG\" data-search=\"ἀπαλλοτριόω apallotrioo alienar afastar alheio Efésios Colossenses Clemente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαλλοτριόω</td><td>Verbo</td><td>alienar; afastar; ficar alheio</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hapalos-bdag\" data-source=\"BDAG\" data-search=\"ἁπαλός hapalos tenro macio figueira broto Mateus Marcos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁπαλός</td><td>Adjetivo</td><td>tenro; macio</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apanainomai-bdag\" data-source=\"BDAG\" data-search=\"ἀπαναίνομαι apanainomai rejeitar repudiar Clemente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπαναίνομαι</td><td>Verbo</td><td>rejeitar; repudiar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apanthropos-bdag\" data-source=\"BDAG\" data-search=\"ἀπάνθρωπος apanthropos desumano torturadores Policarpo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπάνθρωπος</td><td>Adjetivo</td><td>desumano</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-axiopistos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀξιόπιστος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦axiópistos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Adjetivo; veja <span class=\"greek\">ἄξιος</span>, <span class=\"greek\">πιστός</span>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Relativo a ser considerado digno de crédito, confiável, fidedigno.</strong> Xenofonte, Platão e outros; papiros; Pr 28.20; 2Mc 15.11; Josefo, <em>C. Ap.</em> 1.4; Justino, <em>D.</em> 72. A Suda explica: <span class=\"greek\">ἀξιόπιστος οὐχὶ ὁ κατάπλαστος λέγεται ὑπὸ τῶν παλαιῶν καὶ τεραταίᾳ χρώνενος, ἀλλ’ ὁ πιστὸς καὶ δόκιμος καὶ ἀξιόχρεως</span>, isto é, <strong>os antigos chamam ἀξιόπιστος não quem inventa coisas e conta histórias fabulosas, mas quem é confiável, comprovado e digno de crédito</strong>. Na literatura tratada pelo léxico, a palavra é usada em dois níveis de sentido: uma característica tal como percebida ou tradicionalmente projetada e a realidade estabelecida contextualmente. <span class=\"greek\">οἱ δοκοῦντες ἀ. εἶναι καὶ ἑτεροδιδασκαλοῦντες</span>, <strong>os que parecem dignos de confiança e, contudo, ensinam doutrina diferente</strong>, IPol 3.1.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Relativo a ter a aparência de ser confiável, traindo a confiança, pretensioso, especioso.</strong> Luciano, <em>Alex.</em> 4; Cáriton 6.9.7; assim o advérbio em Josefo, <em>Bell.</em> 1.508. <span class=\"greek\">φιλόσοφοι</span>, Dg 8.2. Num oxímoro incisivo, <span class=\"greek\">λύκοι ἀ.</span>, IPhld 2.2. — DELG s.v. <span class=\"greek\">πείθομαι</span>. Spicq.</p>\n</section></article><article id=\"entry-axioplokos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀξιόπλοκος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦axióplokos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἄξιος</span>, <span class=\"greek\">πλέκω</span>. <strong>Dignamente entretecido</strong>: <span class=\"greek\">στέφανος</span>, em sentido figurado, de um grupo de pessoas dignas, IMg 13.1.</p>\n</section></article><article id=\"entry-axioprepes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀξιοπρεπής</h1><div class=\"entry-meta\"><span class=\"greek\">ές</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦axioprepḗs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἄξιος</span>, <span class=\"greek\">πρέπω</span>; Xenofonte, <em>Symp.</em> 8.40; Símaco, Sl 89.16. <strong>Digno de honra</strong>, dos cristãos romanos, IRo ins. <span class=\"greek\">ἀξιοπρεπέστατος ἐπίσκοπος</span>, <strong>o mais estimado supervisor — bispo</strong>, IMg 13.1.</p>\n</section></article><article id=\"entry-axios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄξιος</h1><div class=\"entry-meta\"><span class=\"greek\">ία, ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦áxios⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Desde Homero; empréstimo no rabínico. Adjetivo para <span class=\"greek\">*ἄγ-τιος</span>; compare <span class=\"greek\">ἄγω</span> no sentido de <strong>“fazer descer”</strong> no prato da balança, <strong>“pesar”</strong>; daí <span class=\"greek\">ἄξιος</span> de alguém ou de algo que é avaliado. <strong>Se a avaliação resulta em vantagem ou penalidade depende do contexto ou do emprego de uma partícula negativa.</strong></p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Relativo a possuir grau relativamente alto de valor comparável, correspondente, comparável, digno</strong>, de coisas em relação a outras coisas.</p>\n<p class=\"entry-text\"><strong>a.</strong> Quanto ao preço, <strong>igual em valor</strong>. Eurípides, <em>Alc.</em> 300; Ps.-Demóstenes 13.10; Herodiano 2.3 [do valor de uma coisa]; Pr 3.15; 8.11; Sir 26.15; veja Nägeli 62. <span class=\"greek\">οὐκ ἄξια τὰ παθήματα πρὸς τ. μέλλουσαν δόξαν</span>, <strong>os sofrimentos não são comparáveis à glória por vir</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8.18</a>; compare Arriano, <em>Anab.</em> 6.24.1, <span class=\"greek\">οὐδὲ τὰ ξύμπαντα … ξυμβληθῆναι ἄξια εἶναι τοῖς … πόνοις</span>. <span class=\"greek\">οὐδενὸς ἄ. λόγου</span>, <strong>digno de nenhuma consideração</strong>, Dg 4.1; compare <span class=\"greek\">λόγου ἄ.</span>, Heródoto 4.28; Platão, <em>Ep.</em> 7, 334e; Diodoro Sículo 13.65.3, <span class=\"greek\">οὐδὲν ἄξιον λόγου πράξας</span>; Dionísio de Halicarnasso 1.22.5; Dio Crisóstomo 22 [39], 1; <em>Vit. Hom. et Hes.</em> 4; compare v. 4.</p>\n<p class=\"entry-text\"><strong>b.</strong> Em geral, <strong>correspondente, apropriado</strong>, em qualquer outra relação. Diodoro Sículo 4.11.1, <span class=\"greek\">ἄξιον τῆς ἀρετῆς</span>, <strong>digno de seu valor</strong>; Josefo, <em>Vi.</em> 250, <span class=\"greek\">βοὴ εὐνοίας ἀξία</span>; Justino, <em>A I</em> 4.8, <span class=\"greek\">οὐδὲν ἄ. τῆς ὑποσχέσεως</span>. <span class=\"greek\">καρποὶ ἄ. τῆς μετανοίας</span>, <strong>frutos correspondentes ao arrependimento</strong>, isto é, que mostrem que houve abandono dos caminhos pecaminosos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3.8</a>. Da mesma forma, <span class=\"greek\">ἄ. τῆς μετανοίας ἔργα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 26.20</a>. <span class=\"greek\">καρπὸς ἄ. οὗ ἔδωκεν</span>, <strong>fruto correspondente ao que ele nos deu</strong>, 2Cl 1.3. <span class=\"greek\">ἄ. πρᾶγμα</span>, ISm 11.3; compare Justino, <em>A I</em> 19.5, <span class=\"greek\">ἀ. θεοῦ δύναμιν</span>. <span class=\"greek\">ἄκκεπτα</span>, IPol 6.2. <span class=\"greek\">ἔργα ἄ. τῶν ῥημάτων</span>, <strong>atos correspondentes às palavras</strong>, 2Cl 13.3. <span class=\"greek\">πάσης ἀποδοχῆς ἄ.</span>, <strong>digno de plena aceitação</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 1.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">4.9</a>; Heraclid. Crit. [século III a.C.], Fgm. I 17, <span class=\"greek\">πάσης ἄξιος φιλίας</span>; Justino, <em>D.</em> 3.3, <span class=\"greek\">ἀποδοχῆς ἄξια</span>.</p>\n<p class=\"entry-text\"><span class=\"greek\">οὐδὲν ἄ. θανάτου</span>, <strong>nada digno de morte, nada que mereça a morte</strong>; compare Plutarco, <em>Marcus Cato</em> 349a [21], <span class=\"greek\">ἄξιον … τι θανάτου</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 25.11</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.25\" target=\"_blank\" rel=\"noopener noreferrer\">25</a>. <span class=\"greek\">θανάτου ἢ δεσμῶν ἄ.</span>, <strong>nada que mereça morte ou prisão</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 23.29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.31\" target=\"_blank\" rel=\"noopener noreferrer\">26.31</a>; compare Hipérides 3.14; Apiano, <em>Iber.</em> 31 §124, <span class=\"greek\">ἄξια θανάτου</span>; Josefo, <em>Ant.</em> 11.144; Herm. Wr. 1.20, <span class=\"greek\">ἄ. τοῦ θανάτου</span>. Seguido de oração relativa: <span class=\"greek\">ἄ. ὧν ἐπράξαμεν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23.41</a>.</p>\n<p class=\"entry-text\"><strong>c.</strong> Impessoal, <span class=\"greek\">ἄξιόν ἐστι</span>, <strong>vale a pena, é apropriado, convém</strong>. Hipérides 2.3; 6.3; 4Mc 17.8; EpArist 4; 282; Justino, <em>A II</em> 3.2. Seguido de infinitivo articular — B-D-F §400, 3; Rob. 1059 —, <span class=\"greek\">τοῦ πορεύεσθαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 16.4</a>. <span class=\"greek\">καθὼς ἄ. ἐστιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 1.3</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Relativo a ser correspondentemente apropriado ou adequado, digno, apto, merecedor</strong>, de pessoas.</p>\n<p class=\"entry-text\"><strong>a.</strong> Em bom sentido, embora às vezes negado. A partícula negativa nesses casos produz o equivalente de <span class=\"greek\">ἀνάξιος</span>, <strong>“indigno”</strong>. Com genitivo da coisa de que alguém é digno: <span class=\"greek\">τῆς τροφῆς</span>, <strong>com direito a seu alimento</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10.10</a>; D 13.1s.; <span class=\"greek\">τῆς αἰωνίου ζωῆς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.46\" target=\"_blank\" rel=\"noopener noreferrer\">At 13.46</a>; <span class=\"greek\">τοῦ μισθοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5.18</a>; <span class=\"greek\">πάσης τιμῆς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">6.1</a>; Dio Crisóstomo 14 [31], 93; Luciano, <em>Tox.</em> 3, <span class=\"greek\">τιμῆς ἄ. παρὰ πάντων</span>. <span class=\"greek\">ἄ. μετανοίας</span>, Hs 8.6.1.</p>\n<p class=\"entry-text\">Com genitivo da pessoa: <span class=\"greek\">οὐκ ἔστιν μου ἄ.</span>, <strong>não é digno de mim</strong> = não merece pertencer a mim; talvez <strong>não é adequado a mim</strong>, veja 1 acima, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10.37s.</a>; compare PtK 3 p. 15, 17; D 15.1. <span class=\"greek\">ἄ. θεοῦ</span>, Wsd 3.5; Justino, <em>D.</em> 5.3; IEph 2.1; 4.1; compare 15.1; IRo 10.2. <span class=\"greek\">ὧν οὐκ ἦν ἄ. ὁ κόσμος</span>, <strong>dos quais o mundo não era digno</strong> = “eram bons demais para este mundo”, New Life version, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.38\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11.38</a>.</p>\n<p class=\"entry-text\">Seguido de infinitivo: Marco Aurélio 8.42, <span class=\"greek\">οὔκ εἰμι ἄξιος</span> com infinitivo; BGU 1141, 15 [13 a.C.]; Josefo, <em>Ant.</em> 4.179; Justino, <em>A I</em> 22.1. <span class=\"greek\">οὐκέτι εἰμὶ ἄ. κληθῆναι υἱός σου</span>, <strong>já não sou digno/apto de ser chamado teu filho</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15.19</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">21</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">At 13.25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 4.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">5.2</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">4</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">9</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">12</a> — WvUnnik, BRigaux <em>Festschr.</em> ’70, 445–61 —; B 14.1; IEph 1.3; Mg 14; Tr 13.1; Sm 11.1; Hs 8.2.5. Com genitivo do infinitivo, ParJer 4.5; MPol 10.2.</p>\n<p class=\"entry-text\">Seguido de <span class=\"greek\">ἵνα</span> — B-D-F §393, 4; Rob. 658 —: <span class=\"greek\">ἄ. ἵνα λύσω τὸν ἱμάντα</span>, <strong>bom o bastante para desatar a correia</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1.27</a>; <span class=\"greek\">ἱκανός</span> P66, 75; veja <span class=\"greek\">ἱκανός</span>, fim. Seguido de oração relativa, <span class=\"greek\">ἄ. ἐστιν ᾧ παρέξῃ τοῦτο</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7.4</a>; B-D-F §5, 3b; 379; Rob. 724. Absolutamente — PPetr II, 15 [3], 8, <span class=\"greek\">ἄ. γάρ ἐστιν ὁ ἄνθρωπος</span>; 2Mc 15.21; Justino, <em>D.</em> 39.2, <span class=\"greek\">ὡς ἀξιοί εἰσι</span> —: <span class=\"greek\">ἄ. εἰσιν</span>, <strong>eles merecem</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">16.6</a>. Compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10.11</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.8\" target=\"_blank\" rel=\"noopener noreferrer\">22.8</a>; IEph 2.2; Mg 12; Tr 4.2; IRo 9.2; ISm 9.2; IPol 8.1; B 9.9; 21.8; com negativa ou implicação negativa no contexto, Hs 8.11.1; B 9.9; 14.4.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἄ. τινα ἡγεῖσθαι</span>, Jó 30.1; Hv 2.1.2; 3.3.4; 4.1.3; m 4.2.1; Hs 7.5; Hs 9.28.5, com <span class=\"greek\">ἵνα</span> em algumas dessas passagens de Hermas. <span class=\"greek\">ὁ σωτὴρ ἀξίαν αὐτὴν ἡγήσατο</span>, <strong>o Salvador a considerou digna</strong>, GMary 463, 22. Como epíteto de pessoas, IMg 2. Substantivado, <span class=\"greek\">ἀκούει τῶν ἀξίων</span>, <strong>Deus ouve os dignos</strong>, AcPt Ox 849, 28; compare Justino, <em>A I</em> 52.3. Comparativo <span class=\"greek\">ἀξιώτερος</span>, SIG 218, 25; Hv 3.4.3. Inscrições: Larfeld I, 493s.</p>\n<p class=\"entry-text\"><strong>b.</strong> Num contexto em que a avaliação é qualificada por consequências desagradáveis para a pessoa avaliada. Aélio Aristides 34 p. 650 D., <span class=\"greek\">ἄ. ὀργῆς</span>. <span class=\"greek\">ἄ. πληγῶν</span>, <strong>merecedor de açoites</strong>, Dt 25.2; compare Josefo, <em>Ant.</em> 13.294; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12.48</a>. <span class=\"greek\">ἄ. θανάτου</span>, <strong>merecedor de morte</strong>, Nicolau de Damasco, 90 Fgm. 4 p. 335, 12s. Jac.; Apiano, <em>Bell. Civ.</em> 2.108 §452; Melito, <em>HE</em> 4.26.6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1.32</a>. <span class=\"greek\">καθώς τις ἄξιός ἐστιν</span>, <strong>conforme cada um merece</strong>, Hs 6.3.3, de punições. — JKleist, “Axios” in the Gospels: <em>CBQ</em> 6, ’44, 342–46; KStendahl, <em>Nuntius</em> 7, ’52, 53s. — EDNT. M-M. TW.</p>\n</section></article><article id=\"entry-axioo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀξιόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦axióō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Imperfeito <span class=\"greek\">ἠξίουν</span>, veja B-D-F §328; futuro <span class=\"greek\">ἀξιώσω</span>; 1º aoristo <span class=\"greek\">ἠξίωσα</span>. Passivo: imperativo presente <span class=\"greek\">ἀξιούσθω</span>; 1º futuro <span class=\"greek\">ἀξιωθήσομαι</span>; 1º aoristo <span class=\"greek\">ἠξιώθην</span>, Gn 31.28; perfeito <span class=\"greek\">ἠξίωμαι</span>. Trágicos, Heródoto e posteriores.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Considerar alguém adequado para retribuição ou para receber algo, considerar digno, merecedor.</strong> <span class=\"greek\">τινά τινος</span>, alguém digno de algo: Diodoro Sículo 17.76.3, <span class=\"greek\">τιμῆς ἠξίωσαν αὐτόν</span>; escólio a Nicandro, <em>Alex.</em> 8; 2Mc 9.15; Josefo, <em>Vi.</em> 231; Taciano; Melito, <em>P.</em> 97, 940. <span class=\"greek\">σὲ λόγου</span>, <strong>considerar-te digno de uma discussão</strong>, compare Eurípides, <em>Med.</em> 962, <span class=\"greek\">ἡμᾶς ἀξιοῖ λόγου</span>; MPol 10.2; compare 14.2.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἵνα ὑμᾶς ἀξιώσῃ τ. κλήσεως ὁ θεός</span>, <strong>para que Deus vos considere dignos do chamado</strong> — assim KJV, 20th Century, Goodspeed, REB e outros; <strong>“tornar dignos”, NRSV e outros, carece de apoio lexical</strong> —, chamado ao qual já estais atendendo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 1.11</a>. No passivo, Dg 9.1, em oposição a ser julgado indigno da vida eterna. Também passivo: Diodoro Sículo 16.59.2, <span class=\"greek\">τ. στρατηγίας ἠξιωμένος</span>; escólio a Apolônio de Rodes 4.1212–14a; Josefo, <em>Ant.</em> 2.258, <span class=\"greek\">τιμῆς</span>. <span class=\"greek\">διπλῆς τιμῆς ἀξιοῦσθαι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5.17</a>; compare Taciano 10.2, <span class=\"greek\">τιμῆς καὶ δωρεᾶς</span>. <span class=\"greek\">δόξης</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3.3</a>.</p>\n<p class=\"entry-text\">Em conexão com consequência indesejável: Heródoto 3.145; Diodoro Sículo 16.64.1, <span class=\"greek\">ὑπὸ τοῦ δαιμονίου τιμωρίας ἠξιώθησαν</span>. <span class=\"greek\">χείρονος τιμωρίας</span>, <strong>merecer punição pior</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10.29</a>; Diodoro Sículo 34+35, Fgm. 3, <span class=\"greek\">τῆς αὐτῆς τιμωρίας ἀξιῶσαί τινα</span>.</p>\n<p class=\"entry-text\">Seguido de infinitivo: <span class=\"greek\">οὐδὲ ἐμαυτὸν ἠξίωσα πρὸς σὲ ἐλθεῖν</span>, <strong>não me considerei digno de ir a ti</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7.7</a>; MPol 20.1. No passivo, seguido de infinitivo, <strong>ser considerado digno</strong>: Simplício sobre Epicteto p. 110, 37, <span class=\"greek\">ἀξιοῦσθαι μανθάνειν</span>; Gn 31.28; Justino, <em>D.</em> 123.1, <span class=\"greek\">λαὸς κεκλῆσθαι ἠξιωμένοι</span>; IEph 9.2; 21.2; IMg 2.14; IRo 1.1.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Fazer uma avaliação acerca da adequação de algo, especialmente uma atividade.</strong> Apiano, <em>Bell. Civ.</em> 1.34 §154; Fílon, <em>Spec. Leg.</em> 1.319; Josefo, <em>Ant.</em> 1.307; Justino, <em>A I</em> 68.3 e outros; Atanásio 2.3 e outros.</p>\n<p class=\"entry-text\"><strong>a.</strong> <strong>Julgar, considerar, ser de opinião</strong>, seguido de infinitivo. EpJer 40; Justino, <em>A I</em> 16.14 [acusativo com infinitivo]; 23.1 e outros; Atanásio. <span class=\"greek\">ἠξίου, μὴ συνπαραλαμβάνειν τοῦτον</span>, <strong>ele insistia</strong>, no imperfeito, <strong>que não o levassem consigo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.38\" target=\"_blank\" rel=\"noopener noreferrer\">At 15.38</a>. <span class=\"greek\">ἀξιοῦμεν παρὰ σοῦ ἀκοῦσαι</span>, <strong>gostaríamos de ouvir de ti</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 28.22</a>. Compare Dg 3.2; 7.1.</p>\n<p class=\"entry-text\"><strong>b.</strong> <strong>Pedir, solicitar</strong>, sentido característico do grego posterior, com implicação de avaliação da necessidade e da capacidade do possível doador de satisfazê-la. Xenofonte, <em>Mem.</em> 3.11.12; Herodas 6.79; assim sobretudo na LXX; Justino, <em>D.</em> 106.1. Seguido de infinitivo: Demétrio, 722 Fgm. 1, 6 Jac.; Josefo, <em>Ant.</em> 1.338; Alexandre de Afrodísias, <em>An. Mant.</em> II, 1 p. 184, 2, <span class=\"greek\">ἀξ. παρὰ θεῶν μαθεῖν</span>, <strong>pedir aos deuses para aprender</strong>; Justino, <em>A I</em> 3.12 e outros; Melito, <em>HE</em> 4.26.13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.42\" target=\"_blank\" rel=\"noopener noreferrer\">At 13.42</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.43\" target=\"_blank\" rel=\"noopener noreferrer\">43</a>, ambos v.l.; 1Cl 51.1; 53.5; 59.4. Com acusativo de pessoa e <span class=\"greek\">ἵνα</span>, Hv 4.1.3; somente com acusativo de pessoa, 1Cl 55.6.</p>\n<p class=\"entry-text\">Nas passagens de 1Cl e Hermas, o pedido é dirigido a Deus; assim UPZ 78, 22 [159 a.C.]. Orações por vingança de Reneia em Dssm., <em>LO</em> 352, 354 [LAE 423ss.] = SIG 1181, 1s. [séculos II/I a.C.], <span class=\"greek\">ἐπικαλοῦμαι καὶ ἀξιῶ τ. θεὸν τὸν ὕψιστον</span>. Jr 7.16; 11.14; EpArist 245. — DELG s.v. <span class=\"greek\">ἄξιος</span>. M-M. TW.</p>\n</section></article><article id=\"entry-axios-adv-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀξίως</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦axíōs⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Advérbio de <span class=\"greek\">ἄξιος</span>; Sófocles, Heródoto e posteriores; inscrições, papiros, LXX; ApcEsdr 2.20 p. 26, 12 Tdf.; EpArist 32.39; Justino; Taciano 7.2. <strong>Dignamente, de modo digno de, apropriadamente</strong>, com genitivo em referência a divindade ou pessoa.</p>\n<p class=\"entry-text\"><span class=\"greek\">τοῦ θεοῦ</span>; Hipérides 3.25, <span class=\"greek\">τῆς θεοῦ</span>; Justino, <em>A I</em> 15.5, <em>D.</em> 58.2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 2.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/3JN.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">3Jo 6</a>; compare Pol 5.2; 1Cl 21.1. <span class=\"greek\">τοῦ κυρίου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.10</a>. Sobre essas fórmulas, que têm muitos paralelos em inscrições relativas a pessoas de espírito público, veja Dssm. <em>NB</em> 75s. [BS 248s.]; Nägeli 54; Thieme 21; seu emprego em conexão com cristãos comuns sugere um status extraordinário na nova ordem. <span class=\"greek\">τῶν ἁγίων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 16.2</a>. <span class=\"greek\">ὑπηρετῶν</span>, Dg 11.1.</p>\n<p class=\"entry-text\">Com genitivo de coisa: Diodoro Sículo 1.51.7, <span class=\"greek\">τῆς ἀληθείας ἀ.</span>; Apiano, <em>Bell. Civ.</em> 5.36 §146, <span class=\"greek\">ἀ. τῆς ἀνάγκης</span>, <strong>de modo correspondente à necessidade</strong>; Wsd 7.15. <span class=\"greek\">τοῦ εὐαγγελίου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1.27</a>. <span class=\"greek\">τῆς κλήσεως</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4.1</a>. <span class=\"greek\">τῆς ἐντολῆς</span>, Pol 5.1.</p>\n<p class=\"entry-text\">Sem tal genitivo: <span class=\"greek\">ἀγαπᾶν τινα ἀ.</span>, <strong>amar alguém de maneira apropriada</strong>, isto é, “como a pessoa merece”; compare Tucídides 3.40.8, <span class=\"greek\">κολάσατε ἀξίως τούτους</span>; Wsd 16.1; Sir 14.11; Taciano 7.2; MPol 17.3. — M-M. s.v. <span class=\"greek\">ἄξιος</span>.</p>\n</section></article><article id=\"entry-aoiketos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀοίκητος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aoíkētos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Hesíodo, Heródoto e outros; papiros do período imperial; LXX; TestNapht 3.5, onde Charles põe <span class=\"greek\">ἀ.</span> entre colchetes. <strong>Desabitado, inabitável.</strong> <span class=\"greek\">τὸ χωρίον … γενέσθαι</span>, <strong>a propriedade de Judas tornou-se inabitável</strong>, Papias 3.3; v.l. <span class=\"greek\">ἄοικον</span>, veja o verbete seguinte.</p>\n</section></article><article id=\"entry-aoikos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄοικος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦áoikos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">οἶκος</span>; Hesíodo, trágicos e outros; BGU 372, 13; Fílon; Justino, <em>D.</em> 117.5. Literalmente, <strong>“sem casa”</strong>; daí, <strong>deserto</strong>. Assim em Papias 3.3, v.l., no sentido de <span class=\"greek\">ἀοίκητος</span>; veja o verbete precedente.</p>\n</section></article><article id=\"entry-aoknos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄοκνος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦áoknos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ὀκνέω</span>; Hesíodo e outros; papiros; Pr 6.11a. <strong>Incansável.</strong> <span class=\"greek\">ἀγάπη</span>, IPol 7.2. <span class=\"greek\">ὃν ἀγαπητὸν λίαν ἔχετε καὶ ἄοκνον</span>, <strong>a quem tendes por especialmente querido e que é resoluto</strong>, literalmente <strong>“sem hesitação”</strong>, ibid. Veja o verbete seguinte. — DELG s.v. 1 <span class=\"greek\">ὄκνος</span>.</p>\n</section></article><article id=\"entry-aoknos-adv-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀόκνως</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦aóknōs⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Advérbio de <span class=\"greek\">ἄοκνος</span>; Hipócrates e outros; SIG 762, 30; PSI 621, 6 [século III a.C.]; UPZ 145, 46 [164 a.C.]; Josefo, <em>Ant.</em> 5.238; Atanásio 3.2. No mundo greco-romano, usado a respeito de pessoas que se distinguiam pela prontidão em dedicar-se ao serviço público; além de algumas referências já citadas, veja, por exemplo, IPriene 17, 45; SEG XLI, 1556, 10. <strong>Sem hesitação</strong>: <span class=\"greek\">προσέρχεσθαί τινι</span>, 1Cl 33.8.</p>\n</section></article><article id=\"entry-aoratos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀόρατος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aóratos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ὁράω</span>; Isócrates e outros; LXX, pseudepígrafos; Fílon, Josefo; apologistas, exceto Melito. <strong>Relativo ao que não está sujeito a ser visto, não visto, invisível.</strong></p>\n<p class=\"entry-text\">De Deus: Diodoro Sículo 2.21.7; Cornuto 5 p. 5, 3; Máximo de Tiro 2.10a; 11.9d; PGM 5, 123; 12, 265; 13, 71; Herm. Wr. 11.22; 14.3; Fílon, <em>Op. Mundi</em> 69, <em>Mos.</em> 2.65, <em>Spec. Leg.</em> 1.18; 20; 46 e outros; Josefo, <em>Bell.</em> 7.346; SibOr Fgm. 1, 8; Ar.; Taciano 4.1; Atanásio. HDaxer, <em>Ro 1:18–2:20 im Verh. z. spätjüd. Lehrauffassung</em>, diss. Rostock 1914, 11; compare Ltzm., <em>Hdb.</em> sobre Rm 1.20 [literatura]; FBoll, <em>Studien über Claud. Ptolem.</em> 1894, 68; RBultmann, <em>ZNW</em> 29, 1930, 169–92; EFascher, <em>Deus invisibilis: Marb. Theol. Studien</em> ’31, 41–77. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 1.17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11.27</a>; 2Cl 20.5; PtK 2 p. 13, 24; Dg 7.2.</p>\n<p class=\"entry-text\">De atributos divinos: <span class=\"greek\">δύναμις</span>, compare Fílon, <em>Somn.</em> 2.291; Hv 1.3.4; 3.3.5. <span class=\"greek\">τὰ ἀ. τοῦ θεοῦ</span>, <strong>os atributos invisíveis de Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1.20</a>.</p>\n<p class=\"entry-text\">De Cristo, descrito como <span class=\"greek\">ἀ. ἐπίσκοπος</span>, <strong>supervisor invisível</strong>, IMg 3.2, ou como <span class=\"greek\">ὁ ἀ., ὁ δι’ ἡμᾶς ὁρατός</span>, <strong>o invisível, que por nós se tornou visível</strong>, IPol 3.2. <span class=\"greek\">τὰ ἀ.</span>, <strong>o mundo invisível</strong>, em oposição a <span class=\"greek\">τὰ ὁρατά</span>, o mundo visível, como em Fílon, <em>Congr. Erud. Gr.</em> 25; Taciano 5.1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.16</a>; ITr 5.2; IRo 5.3; IPol 2.2. <span class=\"greek\">ἄρχοντες ὁρατοὶ καὶ ἀ.</span>, <strong>governantes visíveis e invisíveis</strong>, ISm 6.1. <span class=\"greek\">θησαυροὶ ἀ.</span>, <strong>tesouros invisíveis</strong>, B 11.4, Is 45.3. <span class=\"greek\">ψυχή</span>, Fílon, <em>Virt.</em> 57, 172; Dg 6.4. <span class=\"greek\">θεοσέβεια</span>, ibid. — M-M. TW.</p>\n</section></article><article id=\"entry-aorgetos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀόργητος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aórgētos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ὀργή</span>; Aristóteles e outros; termo técnico estoico no sentido de <strong>“sem paixões”</strong>; compare Fílon, <em>Praem.</em> 77, de Moisés. <strong>Livre de ira.</strong> De Deus, com <span class=\"greek\">χρηστός</span>, <span class=\"greek\">ἀγαθός</span> e <span class=\"greek\">ἀληθής</span>, Dg 8.8. <span class=\"greek\">ἀ. ὑπάρχει πρὸς πᾶσαν τ. κτίσιν αὐτοῦ</span>, <strong>Deus é livre de ira para com toda a sua criação</strong>, 1Cl 19.3. <span class=\"greek\">τὸ ἀόργητον αὐτοῦ</span>, <strong>a ausência de paixão dele</strong>, isto é, do supervisor, IPhld 1.2; compare <span class=\"greek\">τὸ ἀ.</span>, Epicteto 3.20.9; Marco Aurélio 1.1. — Sv.</p>\n</section></article><article id=\"entry-apangello-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαγγέλλω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apangéllō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Imperfeito <span class=\"greek\">ἀπήγγελλον</span>; futuro <span class=\"greek\">ἀπαγγελῶ</span>; 1º aoristo <span class=\"greek\">ἀπήγγειλα</span>; perfeito <span class=\"greek\">ἀπήγγελκα</span>, Jz 14.16 cód. B; particípio <span class=\"greek\">ἀπηγγελκότες</span>, Sir 44.3. Passivo: 1º aoristo, 3ª singular, <span class=\"greek\">ἀπηγγέλθη</span>, Justino, <em>A II</em> 2.6; 2º aoristo <span class=\"greek\">ἀπηγγέλην</span>, B-D-F §76, 1; Mlt-H. 226. Veja <span class=\"greek\">ἀγγέλλω</span>; desde Homero.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Dar conta de algo, relatar — inclusive relatar de volta —, anunciar, contar.</strong> Josefo, <em>Vi.</em> 62 e outros; Justino, <em>A II</em> 2.6, nominativo e infinitivo; Taciano 24.1. Com dativo da pessoa: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">14.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.8\" target=\"_blank\" rel=\"noopener noreferrer\">28.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 16.10</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 22.26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.16\" target=\"_blank\" rel=\"noopener noreferrer\">23.16</a>.</p>\n<p class=\"entry-text\">Com dativo de pessoa e acusativo da coisa — Gn 37.5; 42.29; 44.24 e outros —: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.30</a> e outros; 1Cl 65.1; Hs 5.2.11. Somente com acusativo da coisa: <span class=\"greek\">πάντα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8.33</a>. <span class=\"greek\">περί τινος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 1.9</a>. <span class=\"greek\">τί περί τινος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 28.21</a>. <span class=\"greek\">τινὶ περί τινος</span> — Xenofonte, <em>An.</em> 1.7.2; Gn 26.32; Est 6.2; 1Mc 14.21 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">13.1</a>; compare Plutarco, <em>Mor.</em> 509c, <span class=\"greek\">ἐν τούτῳ παρῆσαν οἱ τὴν συμφορὰν ἀπαγγέλοντες</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 16.25</a>. <span class=\"greek\">τί πρός τινα</span> — Hipérides 3.14; Epicteto 3.4.1; 2Rs 15.13 —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.36\" target=\"_blank\" rel=\"noopener noreferrer\">At 16.36</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.38\" target=\"_blank\" rel=\"noopener noreferrer\">38</a> D.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἀ. εἰς τὴν πόλιν</span>, <strong>levar um relato à cidade</strong>, Xenofonte, <em>Hell.</em> 2.2.14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8.34</a>; compare Josefo, <em>Ant.</em> 5.357, <span class=\"greek\">ἀπαγγελθείσης τῆς ἥττης εἰς τὴν Σιλω</span>; Am 4.13; 1Mc 6.5. Usado com <span class=\"greek\">λέγων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.51\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4.51</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 5.22</a>. Com dativo da pessoa seguido de acusativo e infinitivo, IPhld 10.1. Seguido de oração relativa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 4.23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.19\" target=\"_blank\" rel=\"noopener noreferrer\">23.19</a>. Seguido de <span class=\"greek\">πῶς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8.36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 11.13</a>. Seguido de <span class=\"greek\">ὅτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18.37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5.15</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.18\" target=\"_blank\" rel=\"noopener noreferrer\">20.18</a> v.l.; GJs 24.3, Bodmer em lugar de <span class=\"greek\">ἀν-</span>. Com acusativo e infinitivo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 12.14</a>. Seguido de <span class=\"greek\">ὡς</span>, 1Esd 5.37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8.47</a>; B-D-F §396; Rob. 726.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Tornar algo publicamente conhecido, proclamar</strong>, de algo presente ou futuro. <span class=\"greek\">κρίσιν τοῖς ἔθνεσιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12.18</a>. Com <span class=\"greek\">μαρτυρεῖν</span>, <span class=\"greek\">τὴν ζωήν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 1.2</a>; compare v. 3. <span class=\"greek\">τὸ ὄνομά σου τοῖς ἀδελφοῖς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2.12</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἀ. ἐνώπιόν τινος</span>, Sl 141.3, no sentido de <strong>contar aberta ou francamente</strong>, como Gn 12.18; 1Rs 9.19. <span class=\"greek\">ἀπήγγειλεν ἐνώπιον παντὸς τοῦ λαοῦ</span>, <strong>ela confessou diante de todo o povo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8.47</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14.25</a>. Com dativo e infinitivo: <span class=\"greek\">τ. ἔθνεσιν ἀ. μετανοεῖν καὶ ἐπιστρέφειν</span>, <strong>declararam aos gentios que deviam arrepender-se e voltar-se</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 26.20</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.30\" target=\"_blank\" rel=\"noopener noreferrer\">17.30</a> v.l. Seguido de <span class=\"greek\">ἵνα</span>, introduzindo ordem a ser transmitida a outro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28.10</a>; compare Polieno 7.15.2, ordem de Xerxes: <span class=\"greek\">ἄπιτε κ. τοῖς Ἕλλησιν ἀπαγγείλατε, ὅσα ἑωράκατε</span>. — Anz 283s. M-M. TW.</p>\n</section></article><article id=\"entry-apancho-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπάγχω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apánchō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">De <span class=\"greek\">ἄγχω</span>, <strong>“apertar, estrangular”</strong>; 1º aoristo médio <span class=\"greek\">ἀπηγξάμην</span>. Desde Homero; Josefo, <em>Ant.</em> 12.256; 15.176. No médio, <strong>enforcar-se</strong>; assim desde Ésquilo e Heródoto; Epicteto; PSI 177, 10; PGM 4, 1911; 2Rs 17.23; Tb 3.10. — Mlt. 155. De Judas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.5</a>: <span class=\"greek\">ἀπελθὼν ἀπήγξατο</span>, como Epicteto 1.2.3. Veja <span class=\"greek\">Ἰούδας</span> 6.</p>\n</section></article><article id=\"entry-apago-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπάγω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apágō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀπάξω</span>, LXX; 2º aoristo <span class=\"greek\">ἀπήγαγον</span>. Passivo: futuro <span class=\"greek\">ἀπαχθήσομαι</span>, LXX; 1º aoristo <span class=\"greek\">ἀπήχθην</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 12.19</a>; particípio perfeito <span class=\"greek\">ἀπηγμένος</span>; mais-que-perfeito, 3ª singular, <span class=\"greek\">ἀπῆκτο</span>, Gn 40.3. Desde Homero.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Levar ou mover alguém ou algo de um lugar, levar embora, retirar.</strong> Para dar água, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13.15</a>. Com acusativo de pessoa e indicação do destino — Sl 59.11; 3Rs 1.38 —: <span class=\"greek\">με εἰς τὴν Ἀρκαδίαν</span>, Hs 9.1.4; compare Diodoro Sículo 5.51.4, <span class=\"greek\">Διόνυσος ἀπήγαγε τὴν Ἀριάδνην εἰς τὸ ὄρος</span>. <span class=\"greek\">σὲ ἀ. ἐν τῷ ναῷ Κυρίου</span>, GJs 6.1. <span class=\"greek\">ποῦ σε ἀπάξω καὶ σκεπάσω σου τὴν ἀσχημοσύνην;</span>, <strong>para onde te levarei para esconder tua vergonha?</strong>, 17.3. Absolutamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 24.6(7)</a> v.l.; compare o sentido seguinte.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Conduzir uma pessoa de um ponto a outro num processo legal</strong>, termo técnico jurídico.</p>\n<p class=\"entry-text\"><strong>a.</strong> <strong>Levar à presença de.</strong> <span class=\"greek\">πρὸς Καϊάφαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.57\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26.57</a>; <span class=\"greek\">πρὸς τὸν ἀρχιερέα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.53\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14.53</a>; <span class=\"greek\">ἐπὶ βασιλεῖς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21.12</a>; <span class=\"greek\">εἰς τὸ συνέδριον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.66\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22.66</a>; <span class=\"greek\">εἰς τὸ ἱερόν</span>, GJs 15.2; também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.2</a>. De uma testemunha, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 23.17</a>.</p>\n<p class=\"entry-text\"><strong>b.</strong> <strong>Levar embora um prisioneiro ou condenado.</strong> Compare Andócides 4.181; Demóstenes 23.80; PPetr II, 10 [2], 7; PLille 7, 12s., <span class=\"greek\">οὗτος ἀπήγαγέν με εἰς τὸ δεσμοτήριον</span>; OGI 90, 14; Gn 39.22; Fílon, <em>De Jos.</em> 154. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14.44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">15.16</a>; AcPl Ha 4, 13. Compare o uso intransitivo em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 13.10</a> v.l.</p>\n<p class=\"entry-text\"><strong>c.</strong> <strong>Levar para execução.</strong> Diodoro Sículo 13.102.3; POxy 33, I 8 e outros; Sus 45 Theod.; EpJer 17; En 10.13, <span class=\"greek\">εἰς τὸ χάος τοῦ πυρός</span>; Josefo, <em>Bell.</em> 6.155, <em>Ant.</em> 19.269; Justino, <em>A I</em> 31.6 e outros. <span class=\"greek\">ἀ. εἰς τὸ σταυρῶσαι</span>, <strong>levar para crucificar</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.31</a>. Sem complemento — Esopo, <em>Fab.</em> 56 P.; para isso Halm 112 e H-H. 56 trazem <span class=\"greek\">ὑπάγω</span>; Est 1.1o —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23.26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.16\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19.16</a> v.l.; mas veja também <em>P66 Supplement v.l.</em>, ’58, 38. Passivo: <span class=\"greek\">ἐκέλευσεν ἀπαχθῆναι</span>, <strong>ordenou que fossem levados</strong>, à execução, compare Polieno 5.2.16, <span class=\"greek\">ἀπαχθῆναι προσέταξεν</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 12.19</a>. <span class=\"greek\">εἰς Ῥώμην</span>, IEph 21.2.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> Intransitivo, <strong>marcar extensão ao longo de uma rota</strong>. De uma estrada, <strong>levar, conduzir</strong>, como o latim <em>ducere</em>, com <span class=\"greek\">εἴς τι</span>: <em>Vita Aesopi</em> W 4, <span class=\"greek\">ἀπάγουσα ὁδὸς εἰς τὴν πόλιν</span>; Estêvão de Bizâncio [século VI d.C.], <em>Ethnica</em>, ed. Meineke I p. 287, <span class=\"greek\">Εὔτρησις, κώμη … κεῖται παρὰ τ. ὁδὸν τὴν ἐκ Θεσπιῶν εἰς Πλαταιὰς ἀπάγουσαν</span>. <span class=\"greek\">εἰς τ. ἀπώλειαν</span>, <strong>para a destruição</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7.13</a>; TestAbr A 11 p. 90, 7 [Stone p. 28]; B 8 p. 113, 2 [Stone p. 74]. <span class=\"greek\">εἰς τ. ζωήν</span>, v. 14. De pessoas, <strong>partir</strong>, veja <span class=\"greek\">ἄγω</span> 5: <span class=\"greek\">ἀπά̣γ̣ει ἀπὸ τῶν ἀδελφῶν</span>, AcPl Ha 7, 18.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">4.</span> <strong>Fazer afastar-se da conduta correta</strong>; no passivo, <strong>ser desencaminhado, ser levado</strong>. Luciano, <em>Catapl.</em> 26, <span class=\"greek\">πρὸς ὕβριν</span>. <span class=\"greek\">πρὸς τὰ εἴδωλα</span>, <strong>levados aos ídolos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 12.2</a>. <span class=\"greek\">ἡδοναῖς καὶ ἐπιθυμίαις ἀπαγόμενοι</span>, <strong>levados por prazeres e desejos</strong>, Dg 9.1. <span class=\"greek\">ἀπα̣γ̣ο̣μ̣έ̣ν̣ο̣υ̣ς κ̣α̣[ὶ κα]τ̣ανδραπ̣οδ̣ι̣ζ̣ομένο̣υ̣ς</span>, <strong>levados e escravizados</strong>, AcPl Ha 1, 10. — M-M.</p>\n</section></article><article id=\"entry-apathes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαθής</h1><div class=\"entry-meta\"><span class=\"greek\">ές</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦apathḗs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">πάσχω</span>; Teógnis I, 1177 e outros.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Relativo a não estar sujeito ao sofrimento, livre de sofrimento.</strong> Assim Platão e outros; termo estoico, Stoic. II p. 99, 23; Teles p. 56, 14; Porfírio, <em>Abst.</em> 2.61; Herm. Wr. 2.12; Fílon; Josefo, <em>Bell.</em> 5.417; POxy 526, 3s.; Justino; Atanásio. Compare Teógnis 1177; Xenofonte, <em>An.</em> 7.7.33 e outros. De Cristo, em oposição a <span class=\"greek\">παθητός</span>, como em Proclo, <em>Theol.</em> 80 p. 74, 33: IEph 7.2; IPol 3.2.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Relativo a sair de sofrimento ou dano sem infortúnio, sem sofrer, ileso.</strong> Heródoto 1.32; 2.119; Dio Crisóstomo 19 [36], 40, onde Zoroastro sai do fogo ileso; Apiano, <em>Liby.</em> 111 §522; Josefo, <em>Ant.</em> 1.284; também termo médico, por exemplo Galeno 5.122. <span class=\"greek\">Βαρσαβᾶς … ἰὸν ἐχίδνης πιῶν … ἀ. διεφυλάχθη</span>, <strong>Barsabás, embora tivesse bebido veneno de víbora, não sofreu efeito nocivo algum</strong>, Papias 11.2. — TW.</p>\n</section></article><article id=\"entry-apaideutos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαίδευτος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦apaídeutos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">παιδεύω</span>; Eurípides, Platão e outros; PSI 1282, 59, <em>Hymn to Demeter</em>; POxy 2339, 18; BGU 1578, 14; LXX; Fílon; Josefo, <em>Ant.</em> 2.285, <em>C. Ap.</em> 2.37; SibOr 3.670, sobretudo de pessoas; advérbio em Taciano 2.1. <strong>Sem instrução, sem educação, inculto</strong>, com <span class=\"greek\">ἄφρων</span>, <span class=\"greek\">ἀσύνετος</span>, <span class=\"greek\">μωρός</span>, 1Cl 39.1. <span class=\"greek\">ζητήσεις</span>, <strong>especulações sem instrução</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 2.23</a>; compare Xenofonte, <em>Ep.</em> 2 <em>Ad Crit.</em> p. 789, <span class=\"greek\">γνώμη ἀ.</span>; Platão, <em>Phdr.</em> 269b, <span class=\"greek\">ῥῆμα ἀ.</span>. — M-M. TW.</p>\n</section></article><article id=\"entry-apairo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαίρω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apaírō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀπαρῶ</span>; 1º aoristo <span class=\"greek\">ἀπῆρα</span>, LXX; perfeito <span class=\"greek\">ἀπῆρκα</span>; 1º aoristo passivo <span class=\"greek\">ἀπήρθην</span>. Veja <span class=\"greek\">αἴρω</span>; Eurípides, Heródoto e outros; TestSol 26.6; TestLevi 7.4; ParJer 3.8; LXX; Josefo, <em>Bell.</em> 4.87, <em>Vi.</em> 422.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> Transitivo, <strong>tirar, levar embora</strong>, <span class=\"greek\">τινὰ ἀπό τινος</span>; na literatura tratada pelo léxico, somente no passivo. <span class=\"greek\">ὅταν ἀπαρθῇ ἀπ’ αὐτῶν ὁ νυμφίος</span>, <strong>quando o noivo lhes for tirado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2.20</a>; GBraumann, <em>NovT</em> 6, ’63, 264–67; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.35</a>. Entretanto, não há necessidade de supor a ideia de força em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">At 1.9</a> D.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> Intransitivo, <strong>empreender uma viagem, partir, deixar um lugar</strong>; compare nosso “partir”. PPetr II, 13 [5], 5 [século III a.C.], <span class=\"greek\">ἀπηρμένος</span>, <strong>partido em viagem</strong>; compare PLips 47, 12 [século IV d.C.]; POxy 1873, 13 [século V d.C.]. <span class=\"greek\">Παῦλος … ἀπῆρεν εἰς Μακεδονίαν</span>, <strong>Paulo partiu para a Macedônia</strong>, AcPl Ha 5, 26. <span class=\"greek\">ἀπάραντος τοῦ πλοίου</span>, <strong>depois que o barco partiu</strong>, 7, 22. Leitura incerta: <span class=\"greek\">ἀπέ[ρομ]ε εἰς Ῥώμην</span>; Schubart entende <span class=\"greek\">ἀπέρομε = ἀπαίρομαι</span>, 7, 14. — M-M.</p>\n</section></article><article id=\"entry-apaiteo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαιτέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apaitéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">1º aoristo passivo, particípio <span class=\"greek\">ἀπαιτηθείς</span>, Wsd 15.8; futuro passivo, 2ª singular, <span class=\"greek\">ἀπαιτηθήσῃ</span>, Is 30.33; infinitivos <span class=\"greek\">ἀπαιτηθήσεσθαι</span>, Justino, <em>A I</em> 17.4, e <span class=\"greek\">ἀπαιτήσεσθαι</span>, Atanásio 36.1. Veja <span class=\"greek\">αἰτέω</span>; trágicos, Heródoto e posteriores.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Exigir algo de volta ou como devido, pedir de volta, exigir.</strong> De empréstimo — como em “cobrança à vista” — ou de propriedade roubada: Teofrasto, <em>Char.</em> 10.2; Fálaris, <em>Ep.</em> 83.1; 2; SIG 955, 18; papiros, por exemplo BGU 183, 8; PYadin 17, 9 e outros; POxy 3058, 13 [século II d.C.]; Sir 20.15; Fílon, <em>De Jos.</em> 227; Justino, <em>D.</em> 125.2, <span class=\"greek\">τὰ ἴδια παρὰ πάντων</span>. <span class=\"greek\">τί ἀπό τινος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6.30</a>. Com o objeto suprido pelo contexto, <span class=\"greek\">ἀπό τινος</span>, Hs 8.1.5; compare D 1.4. Absolutamente, 1.5.</p>\n<p class=\"entry-text\">Usando a imagem da vida como empréstimo — Cícero, <em>De Rep.</em> 1.3.4; compare Epicteto 4.1.172; Wsd 15.8; outras referências em Horst, <em>Ps.-Phocyl.</em>, p. 190 —: <span class=\"greek\">τὴν ψυχὴν ἀπαιτοῦσιν ἀπὸ σοῦ</span>, <strong>estão exigindo de ti a tua vida</strong>, isto é, <strong>tua vida será exigida de ti</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12.20</a>; v.l. <span class=\"greek\">αἰτοῦσιν</span>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> Em geral, <strong>pedir com nota de urgência, exigir, desejar</strong>. Diodoro Sículo 16.56.3; Dio Crisóstomo 31.3; Josefo, <em>Ant.</em> 12.181; PBerl 11662, 26 [século I d.C.] = Olsson 34, p. 100, <span class=\"greek\">ὁ τόπος ἀπαιτεῖ</span>, <strong>o lugar exige</strong>. <span class=\"greek\">ὁ καιρὸς ἀπαιτεῖ σε</span>, <strong>o momento exige a ti</strong>, isto é, uma pessoa como tu, IPol 2.3; compare Procópio Sofista, <em>Ep.</em> 54, <span class=\"greek\">καιρὸς γράμματα ἀπαιτῶν</span>, <strong>tempo que exige uma carta</strong>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3.15</a> v.l. — DELG s.v. <span class=\"greek\">αἰτέω</span>. M-M. TW.</p>\n</section></article><article id=\"entry-apalgeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαλγέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apalgéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Perfeito <span class=\"greek\">ἀπήλγηκα</span>; de <span class=\"greek\">ἀλγέω</span>, <strong>“sofrer”</strong>; Tucídides 2.61.4 e outros; Fílon, <em>Exs.</em> 135.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Estar tão calejado que já não se é perturbado pelas implicações do que se faz, tornar-se insensível, morto para o sentimento, sem senso do certo e do errado.</strong> Políbio 16.12.7; compare Nägeli 34. <span class=\"greek\">ἀπηλγηκότες</span>, <strong>mortos para todo sentimento</strong>, REB — assim, com variações, a maioria das traduções —, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4.19</a>. Para uma perspectiva diferente, veja 2.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Estar cheio de um pesado senso de perda ou privação, estar desalentado, desanimado.</strong> Políbio 1.35.5, <span class=\"greek\">ἀπηλγηκυίας ψυχάς</span>; Cássio Dio 48.37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4.19</a>. Compare a v.l. <span class=\"greek\">ἀπηλπικότες</span>, <strong>“desesperados”</strong>, e compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">2.12</a>, <span class=\"greek\">ἐλπίδα μὴ ἔχοντες</span>; a falta de esperança os conduz ao vício: <span class=\"greek\">ἑαυτοὺς παρέδωκαν τῇ ἀσελγείᾳ</span>. Veja 1 acima.</p>\n</section></article><article id=\"entry-apallasso-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαλλάσσω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apallássō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀπαλλάξω</span>, LXX; 1º aoristo <span class=\"greek\">ἀπήλλαξα</span>; perfeito, 3ª singular, <span class=\"greek\">ἀπήλλαγεν</span>, 1Rs 14.29. Médio: futuro <span class=\"greek\">ἀπαλλάξομαι</span>, Justino, <em>D.</em> 68.1. Passivo: futuro <span class=\"greek\">ἀπαλλαγήσομαι</span>, TestJob 25.10; 2º aoristo <span class=\"greek\">ἀπηλλάγην</span>; perfeito <span class=\"greek\">ἀπήλλαγμαι</span>. Veja <span class=\"greek\">ἀλλάσσω</span>; Ésquilo, Heródoto e posteriores.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Libertar de um estado ou entidade controladora, libertar, soltar.</strong></p>\n<p class=\"entry-text\"><strong>a.</strong> Ativo, transitivo: <span class=\"greek\">τούτους</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2.15</a>; compare Josefo, <em>Ant.</em> 11.270; 13.363; Justino, <em>A I</em> 57.3; <em>A II</em> 4.4; Orígenes, <em>C. Cels.</em> 4.19.30, <span class=\"greek\">ἵν’ [ὁ Ἰησοῦς] αὐτοὺς ἀπαλλάξῃ τῆς ἁμαρτίας</span>. <span class=\"greek\">αὐτόν</span>, libertá-lo de um espírito maligno, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.40</a> D.</p>\n<p class=\"entry-text\"><strong>b.</strong> Passivo. PTebt 104, 31 e POxy 104, 26, da separação de um cônjuge; PGen 21, 12; Fílon, <em>Spec. Leg.</em> 3.107, de pena de morte. Pessoas enfermas <strong>são libertadas = curadas</strong>, <span class=\"greek\">ἀπὸ πάσης ἀσθενείας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 5.15</a> D; compare Josefo, <em>Ant.</em> 2.33.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> Intransitivo, <strong>ir embora, deixar, partir</strong>. Fílon, <em>Spec. Leg.</em> 2.85; Josefo, <em>Ant.</em> 5.143; Justino, <em>A II</em> 2.7, <em>D.</em> 56.5 e outros; Melito, <em>P.</em> 24, 175. Com <span class=\"greek\">ἀπό τινος</span>: Xenofonte, <em>An.</em> 7.1.4; Flegonte, 257 Fgm. 36, 1, 2 Jac.; Mitt-Wilck. II/2, 284, 12; PRyl 154, 26, <span class=\"greek\">ἀπαλλασσομένης ἀπ’ αὐτοῦ</span>; Justino, <em>D.</em> 126.4, <span class=\"greek\">ἀπαλλάσσονται ἀπὸ Ἀβραάμ</span>, Gn 18.16. De doenças, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 19.12</a>; compare Ps.-Platão, <em>Eryx.</em> 401c, <span class=\"greek\">εἰ αἱ νόσοι ἀπαλλαγείησαν ἐκ τ. σωμάτων</span>; PGM 13, 245.</p>\n<p class=\"entry-text\"><span class=\"greek\">τοῦ κόσμου</span>, <strong>partir do mundo</strong>, eufemismo por <strong>morrer</strong>, 1Cl 5.7. Do mesmo modo <span class=\"greek\">τοῦ βίου</span>: Eurípides, <em>Hel.</em> 102; PFay 19, 19, <span class=\"greek\">ἀπαλλάσσομαι τοῦ βίου</span>; TestAbr A 18 p. 100, 22 [Stone p. 48; ativo]; Atanásio 31.3; MPol 3.1. Absolutamente, Qua, em oposição a <span class=\"greek\">ἐπιδημεῖν</span>. <span class=\"greek\">εἰς οἶκον</span>, <strong>ir para casa</strong>, GPt 14.59 = ASyn. 361, 35; 2Cl 17.3.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Resolver uma questão com um adversário, chegar a um acordo, livrar-se de</strong>; passivo com sentido ativo. Xenofonte, <em>Mem.</em> 2.9.6: um réu “faz tudo” para livrar-se de seu acusador. <span class=\"greek\">δὸς ἐργασίαν ἀπηλλάχθαι ἀπ’ αὐτοῦ</span>, <strong>faz todo o possível para chegar a um acordo com teu adversário</strong>, literalmente <strong>livrar-te dele</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.58\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12.58</a>. — DELG s.v. <span class=\"greek\">ἄλλος</span>. M-M. TW.</p>\n</section></article><article id=\"entry-apallotrioo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαλλοτριόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apallotrióō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀπαλλοτριώσω</span>, LXX; 1º aoristo <span class=\"greek\">ἀπηλλοτρίωσα</span>. Passivo: aoristo <span class=\"greek\">ἀπηλλοτριώθην</span>; particípio perfeito <span class=\"greek\">ἀπηλλοτριωμένος</span>, LXX. Hipócrates, Platão e outros; inscrições, por exemplo IMagnSip 19, 5s. [154/55 d.C.], ISmyrnaMcCabe .0421, 5; papiros, LXX, TestJob; TestBenj 10.10; ApcMos.</p>\n<p class=\"entry-text\"><strong>Alienar, afastar</strong>, <span class=\"greek\">τινά τινος</span>; veja <span class=\"greek\">ἀλλότριος</span>. SIG 495, 164 [século III a.C.]; Sir 11.34; Josefo, <em>Ant.</em> 4.3. <span class=\"greek\">γαμετὰς ἀνδρῶν</span>, <strong>esposas de seus maridos</strong>, 1Cl 6.3. <span class=\"greek\">ἡμᾶς τοῦ καλῶς ἔχοντος</span>, <strong>a nós daquilo que é correto</strong>, 14.2.</p>\n<p class=\"entry-text\">No passivo — Políbio 1.79.6; Ez 14.5, 7; 3Mc 1.3; TestBenj 10.10; Herm. Wr. 13.1, <span class=\"greek\">τ. κόσμου</span> —: <span class=\"greek\">ἀπηλλοτριωμένοι τῆς ζωῆς τοῦ θεοῦ</span>, <strong>alheios à vida de Deus</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4.18</a>. <span class=\"greek\">τῆς πολιτείας τοῦ Ἰσραήλ</span>, <strong>excluídos da vida corporativa de Israel</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">2.12</a>. Com <span class=\"greek\">ἐχθρός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1.21</a>. <em>New Docs</em> 3, 62. — DELG s.v. <span class=\"greek\">ἄλλος</span>. M-M. TW.</p>\n</section></article><article id=\"entry-hapalos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁπαλός</h1><div class=\"entry-meta\"><span class=\"greek\">ή, όν</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hapalós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Desde Homero; PEdg 22, 9 = Sb 6728 [257/56 a.C.], texto restaurado, superlativo, de cevada; LXX; TestNapht 1.7; Josefo, <em>Bell.</em> 2.120; Atanásio 27.1, <span class=\"greek\">ψυξή</span>. <strong>Tenro, macio</strong>, não duro nem resistente. Dos brotos novos da figueira: <span class=\"greek\">ὅταν ὁ κλάδος αὐτῆς ἁ. γένηται</span>, <strong>quando seu ramo se torna tenro</strong>, isto é, brota, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24.32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13.28</a>; expressão favorita a respeito de plantas em Teócrito 5.55; 8.67; 11.57; 15.113. De bezerros, Gn 18.7: <span class=\"greek\">δώδεκα μόσχους ἀ.</span>, GJs 4.3, com variante nos manuscritos; não no papiro.</p>\n</section></article><article id=\"entry-apanainomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπαναίνομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apanaínomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">1º aoristo, 3ª singular, <span class=\"greek\">ἀπηνήνατο</span>, Sl 76.3. De <span class=\"greek\">ἀναίνομαι</span>, <strong>“rejeitar, repelir”</strong>; Homero e outros; PGrenf I, 1 [1], 5; LXX; Justino, <em>D.</em> 117.1. <strong>Rejeitar, repudiar</strong>, com acusativo; compare Hipócrates, <em>Mul.</em> 2.179, em que a esposa <span class=\"greek\">τὸν ἄνδρα ἀπαναίνεται</span>. <span class=\"greek\">νουθέτημα παντοκράτορος</span>, <strong>a admoestação do Todo-Poderoso</strong>, 1Cl 56.6, Jó 5.17.</p>\n</section></article><article id=\"entry-apanthropos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπάνθρωπος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦apánthrōpos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἄνθρωπος</span>; trágicos e outros; Josefo, <em>Ant.</em> 8.117; 16.42; Taciano; papiros, por exemplo PFlor 367, 4 [século III d.C.]. <strong>Desumano</strong>: <span class=\"greek\">βασανισταί</span>, <strong>torturadores desumanos</strong>, MPol 2.3.</p>\n</section></article>"};
